~()?\"']/g, ' ')\n .replace(/\\s+/g,:
~()?"']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Vysoce přesné vyhledávání a sémantický dotazovací engine
 */
exportovat asynchronní funkci searchSentences(
  dotaz:string,
  filtry: SearchFilterOptions = {}
): Slib<{ výsledky: SentenceItem[]; total:number; sémantické shody?: sémantická shoda[] }> {
  const all = wait loadSentences();
  const normalizedQuery = normalizeText(dotaz);
  const queryTokens = normalizedQuery ? normalizedQuery.split(' ').filter(Boolean) : [];

  const {
    cefr = 'všechny',
    sekce = 'vše',
    kategorie = 'všechny',
    podkategorie = 'všechny',
    gramatika = 'vše',
    formalita = 'vše',
    limit = 50,
    offset = 0,
  } = filtry;

  // Průchod filtrem
  nechat filtrovat = all.filter(s => {
    if (cefr !== 'all' && s.cefr !== cefr) return false;
    if (sekce !== 'všechny' && s.sekce !==sekce) return false;
    if (kategorie !== 'všechny' && s.kategorie !== kategorie) return false;
    if (podkategorie !== 'všechny' && s.podkategorie !== podkategorie) return false;
    if (grammar !== 'all' && !s.grammar.toLowerCase().includes(grammar.toLowerCase())) return false;
    if (formalita !== 'vše' && s.formality.toLowerCase() !== formalita.toLowerCase()) return false;
    vrátit true;
  });

  if (!normalizedQuery) {
    const total = filter.length;
    const stránkováno = filtrováno. slice(offset, offset + limit);
    return { výsledky: stránkované, celkem };
  }

  // Algoritmus hodnocení
  interfaceScoredItem {
    item:SentenceItem;
    skóre:číslo;
    aspekt: SemanticExplanationMatch['matchedAspect'];
  }

  const score: ScoredItem[] = [];

  for (const s of filter) {
    nech skóre = 0;
    let matchedAspect: SemanticExplanationMatch['matchedAspect'] = 'angličtina';

    const normEn = normalizeText(s.english);
    const normEg = normalizeText(s.arabicEg);
    const normFusha = normalizeText(s.arabicFusha);
    const normGrammar = normalizeText(s.grammar);
    const normPurpose = normalizovatText(s.purpose);

    // Přesná shoda celé věty
    if (normEn === normalizedQuery) {
      skóre += 100;
      matchedAspect = 'angličtina';
    } else if (normEg === normalizedQuery) {
      skóre += 95;
      matchedAspect = 'arabic-eg';
    } else if (normFusha === normalizedQuery) {
      skóre += 90;
      matchedAspect = 'arabic-fusha';
    }

    //Podřetězec obsahuje
    if (normEn.includes(normalizedQuery)) {
      skóre += 50;
      matchedAspect = 'angličtina';
    } else if (normEg.includes(normalizedQuery)) {
      skóre += 45;
      matchedAspect = 'arabic-eg';
    } else if (normFusha.includes(normalizedQuery)) {
      skóre += 40;
      matchedAspect = 'arabic-fusha';
    } else if (normGrammar.includes(normalizedQuery)) {
      skóre += 35;
      matchedAspect = 'gramatika';
    } else if (normPurpose.includes(normalizedQuery)) {
      skóre += 30;
      matchedAspect = 'koncept';
    }

    // Shoda tokenu
    nechť tokenMatches = 0;
    for (const token of queryTokens) {
      if (normEn.includes(token)) tokenMatches += 5;
      if (normEg.includes(token)) tokenMatches += 4;
      if (normFusha.includes(token)) tokenMatches += 3;
      if (s.vocabulary.some(v => normalizeText(v).includes(token))) tokenMatches += 4;
      if (s.tags.some(t => normalizeText(t).includes(token))) tokenMatches += 3;
    }
    skóre += tokenMatches;

    if (skóre > 0) {
      score.push({ item: s, score, aspekt: matchedAspect });
    }
  }

  score.sort((a, b) => b.score - a.score);

  // Sémantické vysvětlení odpovídá hlavním položkám
  const sémanticMatches: SemanticExplanationMatch[] = score.slice(0, 5).map(s => {
    nech nuance = '';
    if (s.item.grammar.toLowerCase().includes('minulý průběh')) {
      nuance = 'Minulý průběhový čas ukazuje, že událost probíhala v určitém časovém okamžiku v minulosti.';
    } else if (s.item.grammar.toLowerCase().includes('present perfect súvislý')) {
      nuance = 'Přítomný dokonalý průběhový čas zdůrazňuje čas z minulosti a pokračuje až do okamžiku mluvení.';
    } else if (s.item.grammar.toLowerCase().includes('future perfect')) {
      nuance = 'Budoucí dokonalý čas vyjadřuje, že událost bude dokončena před určitým časem v budoucnosti.';
    } else if (s.item.grammar.toLowerCase().includes('indirect')) {
      nuance = 'Forma nepřímé žádosti je vrcholem diplomatické etikety v anglické komunikaci.';
    }
    vrátit {
      věta: s.item,
      podobnost skóre: Math.min(100, s.skóre),
      nuanceExplanationAr: nuance,
      matchedAspect: s.aspect,
    };
  });

  const total = skóroval. délka;
  const paginated = score.slice(offset, offset + limit).map(s => s.item);

  vrátit {
    výsledky: stránkované,
    celkem,
    sémantické shody,
  };
}

/**
 * Deterministická denní věta (identická pro všechny uživatele v daný den)
 */
exportovat asynchronní funkci getDailySentence(): Promise<SentenceItem | null> {
  const all = wait loadSentences();
  if (all. length === 0) return null;

  const today = new Date();
  const dayOfYear = Math.floor(
    (today.getTime() - nové datum(today.getFullYear(), 0, 0).getTime()) / 1000 / 60 / 60 / 24
  );
  const index = Math.abs((dayOfYear * 97 + today.getFullYear()) % all.length);
  vrátit vše[index] || vše[0];
}

/**
 * Deterministická věta týdne
 */
export asynchronní funkce getSentenceOfTheWeek(): Promise<SentenceItem | null> {
  const all = wait loadSentences();
  if (all. length === 0) return null;

  const today = new Date();
  const weekNumber = Math.ceil(
    ((today.getTime() - nové datum(today.getFullYear(), 0, 1). getTime()) / 86400000 + 1) / 7
  );
  // Pro větu týdne preferujte B2 nebo C1
  const b2c1 = all.filter(s => s.cefr === 'B2' || s.cefr === 'C1');
  const pool = b2c1.length > 0 ? b2c1:vše;
  const index = Math.abs((weekNumber * 31) % pool.length);
  návratový fond[index] || bazén[0];
}

/**
 * Získejte náhodnou větu, volitelný CEFR nebo filtr sekcí
 */
export asynchronní funkce getRandomSentence(cefr?: CEFRLevel, sekce?: řetězec): Promise<SentenceItem | null> {
  const all = wait loadSentences();
  nechat pool = všichni;
  if (cefr) {
    pool = pool.filter(s => s.cefr === cefr);
  }
  if (sekce) {
    bazén = bazén. filtr(s => s. sekce === sekce);
  }
  if (pool. length === 0) return null;
  const randIdx = Math.floor(Math.random() * pool.length);
  návratový fond[randIdx];
}
